package main

import (
    "fmt"
    "os"
    "os/exec"
    "time"
)

func main() {
    f, err := os.OpenFile("build/clip.log", os.O_CREATE|os.O_APPEND|os.O_WRONLY, 0o644)
    if err != nil {
        panic(err)
    }
    defer f.Close()
    last := ""
    for {
        out, _ := exec.Command("pbpaste").Output()
        if s := string(out); s != last {
            fmt.Fprintf(f, "%s %q\n", time.Now().Format(time.RFC3339), s)
            last = s
        }
        time.Sleep(500 * time.Millisecond)
    }
}

