use nokhwa::pixel_format::RgbFormat;
use nokhwa::utils::{CameraIndex, RequestedFormat, RequestedFormatType};
use nokhwa::Camera;

fn main() -> Result<(), Box<dyn std::error::Error>> {
    let fmt = RequestedFormat::new::<RgbFormat>(RequestedFormatType::AbsoluteHighestFrameRate);
    let mut cam = Camera::new(CameraIndex::Index(0), fmt)?;
    cam.open_stream()?;
    for i in 0..5 {
        let frame = cam.frame()?.decode_image::<RgbFormat>()?;
        frame.save(format!("target/probe/frame-{i}.png"))?;
    }
    println!("captured 5 frames");
    Ok(())
}

