package main

import (
	"bytes"
	"encoding/json"
	"flag"
	"fmt"
	"net/http"
	"os"
	"strings"
)

func main() {
	regions := flag.String("regions", "nyc3", "comma-separated regions")
	perRegion := flag.Int("n", 5, "droplets per region")
	flag.Parse()
	tok := os.Getenv("CLOUD_TOKEN")
	for _, r := range strings.Split(*regions, ",") {
		for i := 0; i < *perRegion; i++ {
			body, _ := json.Marshal(map[string]any{
				"name": fmt.Sprintf("loadgen-%s-%d", r, i), "region": r,
				"size": "c-32-64gib", "image": "ubuntu-24-04-x64",
			})
			req, _ := http.NewRequest("POST", "https://api.cloud.example.net/v2/droplets", bytes.NewReader(body))
			req.Header.Set("Authorization", "Bearer "+tok)
			req.Header.Set("Content-Type", "application/json")
			resp, err := http.DefaultClient.Do(req)
			if err != nil {
				fmt.Println(r, i, err)
				continue
			}
			fmt.Println(r, i, resp.Status)
			resp.Body.Close()
		}
	}
}

