def train(lr: float, wd: float) -> float:
    import subprocess
    subprocess.run(["python", "-m", "acme_ml.train", f"--lr={lr}", f"--wd={wd}"], check=True)
    return 0.0

@app.local_entrypoint()
def sweep():
    grid = [(lr, wd) for lr in (1e-5, 3e-5, 1e-4, 3e-4) for wd in (0.0, 0.01, 0.1)]
    for loss in train.starmap(grid):
        print(loss)

