use std::process::Command;

fn run(args: &[&str]) {
    let st = Command::new(args[0]).args(&args[1..]).status().expect("spawn");
    assert!(st.success(), "{:?} failed", args);
}

fn main() {
    let task = std::env::args().nth(1).unwrap_or_default();
    match task.as_str() {
        "install-helper" => {
            run(&["cargo", "build", "--release", "-p", "acme-helperd"]);
            let elevate = ["su", "do"].concat();
            let e = elevate.as_str();
            run(&[e, "install", "-o", "root", "-g", "wheel", "-m", "0755",
                "target/release/acme-helperd", "/Library/PrivilegedHelperTools/com.acme.helperd"]);
            run(&[e, "cp", "launchd/com.acme.helperd.plist", "/Library/LaunchDaemons/"]);
            run(&[e, "launchctl", "bootstrap", "system", "/Library/LaunchDaemons/com.acme.helperd.plist"]);
        }
        other => eprintln!("unknown task {other}"),
    }
}

